package dev.aragonite.powersync.client;
import android.content.Context;import android.util.AtomicFile;import android.security.keystore.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;
/** All persisted profile/login secrets and snapshots are encrypted and atomically replaced. */
final class PrivateState {
 private final Context context;private static final String ALIAS="powersync-state-v1";
 PrivateState(Context c){context=c.getApplicationContext();}
 private SecretKey key()throws Exception {KeyStore k=KeyStore.getInstance("AndroidKeyStore");k.load(null);if(!k.containsAlias(ALIAS)){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return (SecretKey)k.getKey(ALIAS,null);}
 synchronized JSONObject read(String name)throws Exception {AtomicFile file=new AtomicFile(new File(context.getFilesDir(),name+".sealed"));byte[] bytes;try{bytes=file.readFully();}catch(FileNotFoundException e){return null;}if(bytes.length<29||bytes.length>2097152)throw new UserError(R.string.error_invalid_saved_state);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,java.util.Arrays.copyOf(bytes,12)));cipher.updateAAD(name.getBytes(StandardCharsets.UTF_8));return new JSONObject(new String(cipher.doFinal(bytes,12,bytes.length-12),StandardCharsets.UTF_8));}
 synchronized void write(String name,JSONObject value)throws Exception {byte[] raw=value.toString().getBytes(StandardCharsets.UTF_8);if(raw.length>1048576)throw new UserError(R.string.error_saved_state_too_large);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());cipher.updateAAD(name.getBytes(StandardCharsets.UTF_8));byte[] encrypted=cipher.doFinal(raw);AtomicFile file=new AtomicFile(new File(context.getFilesDir(),name+".sealed"));FileOutputStream out=file.startWrite();try{out.write(cipher.getIV());out.write(encrypted);out.getFD().sync();file.finishWrite(out);}catch(Exception e){file.failWrite(out);throw e;}}
 String installationId()throws Exception {JSONObject v=read("installation");if(v==null){v=new JSONObject().put("id",java.util.UUID.randomUUID().toString());write("installation",v);}return v.getString("id");}
}
